INSERT INTO `navi_comment` VALUES (/*comment_id*/7001, /*where_type*/7, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'偶尔帮帮忙不也挺好的吗？\n我也会出一份力的', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/7002, /*where_type*/7, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'似乎能和很多勇士一起战斗呢\n主人的话，一定可以大放异彩吧', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/7003, /*where_type*/7, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'要和大家一起战斗咯！\n加油☆', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/10001, /*where_type*/10, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'宝石可以交换食物……\n不，贵重物品！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/10002, /*where_type*/10, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'宝石要\n慎重使用，\n禁止浪费！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/10003, /*where_type*/10, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'主人可以用宝石\n购买贵重物品。\n但是，随便浪费\n是『不可以』的哦。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/10004, /*where_type*/10, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'只要有宝石\n好像就可以交换贵重物品。\n要爱惜地使用哦。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/12001, /*where_type*/12, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'达成特定条件\n就可以获取报酬！\n加油吧♪　', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/13001, /*where_type*/13, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'有这么多的回忆呢\n虽然发生了很多事\n偶尔回顾一下也不错呀', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/13002, /*where_type*/13, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'和主人共度的欢乐日子...\n在这里想看几次都可以哦♪', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/13003, /*where_type*/13, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'这里满载着和大家\n一起度过的珍贵回忆呢。\n我想和大家一起回顾，\n将它们深深刻在心里。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/13004, /*where_type*/13, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'可以看到这么多\n和女孩子之间的回忆呢！\n咻——咻——♪\n真受欢迎啊☆', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/14001, /*where_type*/14, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'这里是可以获得\n培养时所需道具的关卡。\n为了主人，\n我想变得更强。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/14002, /*where_type*/14, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'攻略这个关卡后，\n似乎可以获得道具哦。\n为了变得更强，\n我会全力以赴的！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/14003, /*where_type*/14, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'只要通关这场战斗，\n就可以拿到道具哦\n收集更多\n变得更强吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/14004, /*where_type*/14, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'攻略关卡后，\n可以获取道具。\n能拿的东西，\n当然全部拿光！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/15001, /*where_type*/15, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'主人，做好旅途的准备\n度过更充实的冒险生活吧', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/16001, /*where_type*/16, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'我说……要不要加入行会试试？\n一个人玩确实挺有趣的，但和大家\n一起玩会很热闹，我觉得也不错哦。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/16002, /*where_type*/16, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'要加入行会吗？\n和大家一起冒险\n更开心哦！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/16003, /*where_type*/16, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'好像可以加入行会哦。\n要不要加入看看？\n看起来很有趣呢♪', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/16004, /*where_type*/16, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'可以在这里加入行会。\n有这么多出色的行会，\n简直让人眼花缭乱呢', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/17002, /*where_type*/17, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'在这里可以回顾\n和同伴们一起\n参加团队战的英姿', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/17004, /*where_type*/25, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'模拟战战绩上\n如果有你感兴趣的\n可以把它记录下来', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/17005, /*where_type*/25, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'主人，这次团队战，\n您的活跃表现已经被记录下来了\n将它作为战斗的参考吧', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/17006, /*where_type*/25, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'这次的团队战\n感觉怎么样？\n看一看战绩，或许能总结经验，\n在下次战斗中派上用场哦。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/17007, /*where_type*/25, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'可以重看这次\n团队战的战绩哦！\n也让我看看吧☆', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/18001, /*where_type*/18, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'欢迎光临！\n在这里可以\n更换或者购买\n公会之家的背景音乐。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/18002, /*where_type*/18, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'可以在这里更换\n或者购买背景音乐哦\n我为你准备了很多\n好听的音乐！', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/19001, /*where_type*/19, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'可以更换\n公会之家的背景音乐哦。\n让我也听听\n你喜欢的乐曲吧。', /*voice_id*/3, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/19002, /*where_type*/19, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'这里可以\n更换背景音乐哦\n想要换成哪首歌曲呢？\n嘻嘻嘻，我也很期待♪', /*voice_id*/4, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/20001, /*where_type*/20, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'可以在这里\n购买背景音乐哦\n也可以进行试听，\n请随意挑选', /*voice_id*/5, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/20002, /*where_type*/20, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'欢迎光临！\n这里可以购买背景音乐\n有很多好听的歌曲，\n简直让人目不暇接呢', /*voice_id*/6, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-470.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/21001, /*where_type*/21, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'这里好像可以把获得的道具\n制作成专用装备\n收集好道具的话\n就快点试试制作吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/21002, /*where_type*/21, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'攻略后\n会获得珍贵的道具哦\n用道具可以制作出\n专用装备', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/21003, /*where_type*/21, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'想要专用装备的话，\n挑战这个关卡就好。\n用收集到的素材\n变得更加强大吧。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/21004, /*where_type*/21, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'可以获得制作\n专用装备的道具呢。\n多多收集，让自己\n变得更强大吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/22001, /*where_type*/22, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'请在这里投票\n为你想要\n支持的女孩投上\n充满感情的一票吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-430.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/22002, /*where_type*/22, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'欢迎！\n你喜欢的是\n哪位女孩呢？\n请为她加油哦！', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-430.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/23001, /*where_type*/23, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'感谢\n你的投票\n尽请期待\n最终结果吧！', /*voice_id*/3, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-430.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/23002, /*where_type*/23, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'目前正在\n统计人气投票\n在结果出来之前\n请再稍等一下哦', /*voice_id*/4, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-430.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24001, /*where_type*/24, /*character_id*/109001, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'您帮我制作的\n巧克力蛋糕\n不可能不好吃', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/4.08, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24002, /*where_type*/24, /*character_id*/109001, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'您不可能\n会再次失败的\n再挑战一次试试吧', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/5.0, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24003, /*where_type*/24, /*character_id*/109001, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'这个蛋糕\n是想要送给您的\n没想到\n您竟然会来帮忙……呵呵', /*voice_id*/3, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/10.11, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24004, /*where_type*/24, /*character_id*/109001, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'不用太担心哦\n接下来，我会好好\n花时间教您的', /*voice_id*/4, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/4.0, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24005, /*where_type*/24, /*character_id*/109001, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'这次是状态不太好吗？……\n只要是您帮忙做的东西\n不管是什么样子，我都不在意……呵呵', /*voice_id*/5, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/6.0, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24006, /*where_type*/24, /*character_id*/109002, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'您亲手做的\n巧克力蛋糕\n对我来说是宝物……\n我不会让侮辱它的人活下来的', /*voice_id*/6, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24007, /*where_type*/24, /*character_id*/109002, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'做得很好，真了不起！\n您做的巧克力蛋糕\n和您非常相称', /*voice_id*/7, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24008, /*where_type*/24, /*character_id*/109002, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'帮助了我之后，您已经成为了\n我的俘虏……\n我要邀请您去甜美的世界', /*voice_id*/8, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24009, /*where_type*/24, /*character_id*/109002, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'我已经收到\n您的爱意了\n这是……我们两人\n第一次合作呢……呵呵', /*voice_id*/9, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24010, /*where_type*/24, /*character_id*/109002, /*face_type*/1, /*character_name*/'惠理子（情人节）', /*description*/'这是世界上最棒的\n巧克力蛋糕\n因为，这是您精心\n制作的', /*voice_id*/10, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24011, /*where_type*/24, /*character_id*/109101, /*face_type*/1, /*character_name*/'静流（情人节）', /*description*/'没能顺利完成，觉得很可惜？\n但是，弟弟的心意让我觉得很开心\n不管什么时候，姐姐\n都会在你身边的哦♪', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/2.12, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24012, /*where_type*/24, /*character_id*/109101, /*face_type*/5, /*character_name*/'静流（情人节）', /*description*/'嗯，难得见到弟弟你\n这么紧张啊？\n要不要再试试？', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/4.19, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24013, /*where_type*/24, /*character_id*/109101, /*face_type*/2, /*character_name*/'静流（情人节）', /*description*/'你帮了姐姐\n的大忙！\n啊——\n不能偷吃哦！', /*voice_id*/3, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/2.3, /*change_face_type*/4, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24014, /*where_type*/24, /*character_id*/109102, /*face_type*/1, /*character_name*/'静流（情人节）', /*description*/'快看快看！\n海绵蛋糕烤得很好看哦\n真不愧是弟弟！', /*voice_id*/4, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24015, /*where_type*/24, /*character_id*/109101, /*face_type*/5, /*character_name*/'静流（情人节）', /*description*/'好啦好啦，不要那么难过\n虽然看起来……挺有个性的，\n但是味道肯定不会差！', /*voice_id*/5, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/5.23, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24016, /*where_type*/24, /*character_id*/109102, /*face_type*/1, /*character_name*/'静流（情人节）', /*description*/'像弟弟一样可爱的\n蛋糕做好了！\n快点来尝尝看吧♪', /*voice_id*/6, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24017, /*where_type*/24, /*character_id*/109101, /*face_type*/1, /*character_name*/'静流（情人节）', /*description*/'咦？　弟弟，你的指尖\n沾到巧克力了哦？\n姐姐来帮你舔掉吧，\n唔嗯！', /*voice_id*/7, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-385.0, /*pos_y*/8.0, /*change_face_time*/5.01, /*change_face_type*/2, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24018, /*where_type*/24, /*character_id*/109102, /*face_type*/1, /*character_name*/'静流（情人节）', /*description*/'越来越像模像样了呀？\n不过弟弟还能做得更好的！\n姐姐相信你哦', /*voice_id*/8, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24019, /*where_type*/24, /*character_id*/109102, /*face_type*/1, /*character_name*/'静流（情人节）', /*description*/'哇～\n看起来很好吃！\n弟弟已经很熟练了，\n姐姐能放心地交给你了呢！', /*voice_id*/9, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/24020, /*where_type*/24, /*character_id*/109102, /*face_type*/1, /*character_name*/'静流（情人节）', /*description*/'呀～弟弟帮忙做的\n巧克力蛋糕！\n看起来很好吃呢♪', /*voice_id*/10, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/10011, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/26001, /*where_type*/26, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'前方似乎是神圣之地。\n不知道会沉睡着什么样的宝藏呢，\n好期待接下来的探索♪', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/26002, /*where_type*/26, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'前方似乎是\n神圣之地！\n究竟会找到怎样的宝物呢，\n好期待啊！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/26003, /*where_type*/26, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'前方似乎是神圣之地。\n虽然能获得非比寻常的宝藏，\n但如果不当心的话，\n会吃苦头的。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/26004, /*where_type*/26, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'前方是\n神圣之地。\n打起精神来，\n去调查和探寻宝物吧。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/27001, /*where_type*/27, /*character_id*/106401, /*face_type*/2, /*character_name*/'雪菲', /*description*/'这里沉睡着\n能获得更强力量的道具……\n大家是这么说的。呵呵，\n那我们挑战看看吧。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/27002, /*where_type*/27, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'这里似乎沉睡着\n能获得更强力量的道具！\n从哪里开始挑战呢，\n好迷茫啊！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/27003, /*where_type*/27, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'这里似乎沉睡着\n能获得更强力量的道具！\n不断挑战，\n变得更强吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/27004, /*where_type*/27, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'这里似乎沉睡着\n能获得更强力量的道具。\n主人，我们要从哪里\n开始挑战呢。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/28001, /*where_type*/28, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'欢迎光临！\n公会管理协会\n会协助大家\n拥有美妙的邂逅！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/28002, /*where_type*/28, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'这里是公会管理协会\n请在此处\n确认好友相关事宜', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/29001, /*where_type*/29, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'这里显示了\n各位好友的信息\n请构筑起\n美妙的关系吧！', /*voice_id*/3, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/29002, /*where_type*/29, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'可以在这里的一览处\n确认好友的\n简介哦', /*voice_id*/4, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/30001, /*where_type*/30, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'这里是\n好友管理\n要期待\n能遇见新的好友哦！', /*voice_id*/5, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/30002, /*where_type*/30, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'可以申请\n或同意好友哦\n请开始友好的交流吧！', /*voice_id*/6, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/31001, /*where_type*/31, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'去战斗吧，\n试着较量一下！\n这能检验出你的实力哦，\n请加油！', /*voice_id*/7, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/31002, /*where_type*/31, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'和你在意的队伍\n进行战斗吧！\n究竟哪一边会胜利呢，\n我也很期待', /*voice_id*/8, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/32001, /*where_type*/32, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'我为各位新手\n准备了\n特别任务！\n请务必挑战一下！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/32002, /*where_type*/32, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'限时活动\n正在举办中！\n向任务\n发起挑战吧！', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/33001, /*where_type*/33, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'去给成为好友的\n新手加油吧！\n优厚的报酬在等着你哦！', /*voice_id*/3, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/33002, /*where_type*/33, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'限时活动\n正在举办中！\n向任务\n发起挑战吧！', /*voice_id*/4, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/34001, /*where_type*/34, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'辛苦了！\n可以在这里\n领取任务报酬哦！', /*voice_id*/5, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/34002, /*where_type*/34, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'在这里\n领取任务报酬！\n请注意\n不要漏领哦！', /*voice_id*/6, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-409.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/38001, /*where_type*/38, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'可以享受\n过去的剧情活动哦！\n如果有没参加过的活动，\n不如我们一起去挑战吧?', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-458.0, /*pos_y*/0.0, /*change_face_time*/5.3, /*change_face_type*/2, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/38002, /*where_type*/38, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'好像可以让过去登场过的\n活动限定角色成为同伴，\n还可以获得\n记忆碎片呢。超棒的对吧☆', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-458.0, /*pos_y*/0.0, /*change_face_time*/6.5, /*change_face_type*/2, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/39005, /*where_type*/39, /*character_id*/105801, /*face_type*/3, /*character_name*/'佩可莉姆', /*description*/'', /*voice_id*/0, /*start_time*/'2022/4/1', /*end_time*/'2022/4/8 23:59:59', /*pos_x*/9999.0, /*pos_y*/9999.0, /*change_face_time*/0.0, /*change_face_type*/3, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/40001, /*where_type*/40, /*character_id*/190801, /*face_type*/1, /*character_name*/'花凛', /*description*/'可以回顾\n过往\n出过的题目了，\n复习很重要哦♪', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:00', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-430.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/41001, /*where_type*/41, /*character_id*/106401, /*face_type*/1, /*character_name*/'雪菲', /*description*/'似乎可以在这里\n小试身手。\n很适合用来\n评估一下自己的实力。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:02', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/41002, /*where_type*/41, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'在这里\n试试身手吧！\n全力以赴，\n加油冲！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:03', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/41004, /*where_type*/41, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'可以试试身手了。\n在这里反复练习，然后\n把经验活用在实战中吧。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:04', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/42001, /*where_type*/42, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'似乎能根据训练成果\n得到相应的报酬。\n让我们一起努力吧。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:05', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/42002, /*where_type*/42, /*character_id*/106401, /*face_type*/1, /*character_name*/'雪菲', /*description*/'好像达到目标\n就能得到报酬。\n值得去努力一下呢。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:06', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/2104010);
INSERT INTO `navi_comment` VALUES (/*comment_id*/42003, /*where_type*/42, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'努力参战就能\n得到报酬哦。\n让我们去挑战吧☆', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:07', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/42004, /*where_type*/42, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'完成任务\n就能获得报酬。\n我们一起挑战吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:08', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/43001, /*where_type*/43, /*character_id*/105801, /*face_type*/1, /*character_name*/'佩可莉姆', /*description*/'在这里可以\n参加竞技场的战斗哦！\n调整编队，\n向对手发起挑战吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:09', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/43002, /*where_type*/43, /*character_id*/105901, /*face_type*/1, /*character_name*/'可可萝', /*description*/'在这里可以\n参加竞技场的战斗。\n用主人独特的编队\n向对手发起挑战吧。', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:10', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/43003, /*where_type*/43, /*character_id*/106001, /*face_type*/1, /*character_name*/'凯露', /*description*/'在这里可以\n参加竞技场的战斗哦！\n认真考虑怎么编队，\n向对手发起挑战吧！', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:11', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-363.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/43004, /*where_type*/44, /*character_id*/123001, /*face_type*/1, /*character_name*/'爱梅斯', /*description*/'完成任务\n就能获得报酬哦。\n赶紧多多完成任务，\n好好提升实力吧♪', /*voice_id*/1, /*start_time*/'2020/01/01 0:00:12', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/43005, /*where_type*/44, /*character_id*/123001, /*face_type*/1, /*character_name*/'爱梅斯', /*description*/'现在不是发呆的时候。\n赶快完成任务\n领取报酬吧！', /*voice_id*/2, /*start_time*/'2020/01/01 0:00:13', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/1, /*event_id*/0, /*unlock_story_id*/0);
INSERT INTO `navi_comment` VALUES (/*comment_id*/43006, /*where_type*/45, /*character_id*/123001, /*face_type*/1, /*character_name*/'爱梅斯', /*description*/'喂，报酬不是\n可以领取了吗！\n别忘了检查一下。\n这是和爱梅斯大人的约定哦？', /*voice_id*/3, /*start_time*/'2020/01/01 0:00:14', /*end_time*/'2099/12/31 23:59:59', /*pos_x*/-416.5, /*pos_y*/0.0, /*change_face_time*/5.79, /*change_face_type*/2, /*event_id*/0, /*unlock_story_id*/0);
